//! JSON test vectors for the ordered log tree (docs/merkle-trees.md §3.7):
//! empty tree, single leaf, two leaves, odd and even counts around
//! power-of-two boundaries (1..=9 leaves), a domain-separation negative, an
//! inclusion proof at each position of a 9-leaf tree, and a consistency proof
//! between sizes 6 and 9. The vector file was generated by an independent
//! implementation of the spec; this test recomputes every value.

use membrane_core::log_tree::{leaf_hash, mth, ConsistencyProof, InclusionProof, OrderedLogTree};
use serde::Deserialize;

#[derive(Deserialize)]
struct Vectors {
    domain: String,
    entries: Vec<String>,
    roots: Vec<String>,
    inclusion_proofs: Vec<InclusionVector>,
    consistency_proof: ConsistencyVector,
    domain_separation_negative: NegativeVector,
}

#[derive(Deserialize)]
struct InclusionVector {
    index: u64,
    tree_size: u64,
    path: Vec<String>,
}

#[derive(Deserialize)]
struct ConsistencyVector {
    first_size: u64,
    second_size: u64,
    path: Vec<String>,
}

#[derive(Deserialize)]
struct NegativeVector {
    entry: String,
    two_leaf_root: String,
}

fn decode_hex(s: &str) -> Vec<u8> {
    hex::decode(s).expect("vector is hex")
}

fn decode_root(s: &str) -> [u8; 32] {
    decode_hex(s).try_into().expect("root is 32 bytes")
}

#[test]
fn log_tree_test_vectors() {
    let text = include_str!("data/log_tree_vectors.json");
    let vectors: Vectors = serde_json::from_str(text).expect("parse vectors");

    assert_eq!(vectors.domain, "membrane-log/v1");
    let entries: Vec<Vec<u8>> = vectors.entries.iter().map(|e| decode_hex(e)).collect();
    assert_eq!(entries.len(), 9);
    assert_eq!(vectors.roots.len(), 10, "roots for 0..=9 leaves");

    // Roots: empty tree, single leaf, two leaves, and every count 1..=9
    // (odd and even counts around power-of-two boundaries).
    for (n, expected) in vectors.roots.iter().enumerate() {
        let tree = OrderedLogTree::new(entries[..n].to_vec());
        assert_eq!(tree.root_hex(), *expected, "root for {n} entries");
        assert_eq!(tree.tree_size(), n as u64);
    }
    let full = OrderedLogTree::new(entries.clone());
    let full_root = full.root();

    // Inclusion proof at each position of the 9-leaf tree.
    assert_eq!(vectors.inclusion_proofs.len(), 9);
    for v in &vectors.inclusion_proofs {
        assert_eq!(v.tree_size, 9);
        let proof = InclusionProof {
            leaf_index: v.index,
            tree_size: v.tree_size,
            path: v.path.iter().map(|h| decode_root(h)).collect(),
        };
        assert_eq!(
            proof,
            full.inclusion_proof(v.index).unwrap(),
            "proof shape at index {}",
            v.index
        );
        assert!(
            proof.verify(&entries[v.index as usize], &full_root),
            "proof verifies at index {}",
            v.index
        );
    }

    // Consistency proof between sizes 6 and 9.
    let cv = &vectors.consistency_proof;
    assert_eq!((cv.first_size, cv.second_size), (6, 9));
    let proof = ConsistencyProof {
        first_size: cv.first_size,
        second_size: cv.second_size,
        path: cv.path.iter().map(|h| decode_root(h)).collect(),
    };
    assert_eq!(proof, full.consistency_proof(6).unwrap());
    assert!(proof.verify(&mth(&entries[..6]), &full_root));

    // Domain-separation negative: leaf bytes reinterpreted as a node must not
    // verify.
    let neg = &vectors.domain_separation_negative;
    let fake_entry = decode_hex(&neg.entry);
    let two_leaf_root = decode_root(&neg.two_leaf_root);
    assert_ne!(leaf_hash(&fake_entry), two_leaf_root);
    let two_leaf = OrderedLogTree::new(entries[..2].to_vec());
    assert_eq!(two_leaf.root(), two_leaf_root);
    let proof = two_leaf.inclusion_proof(0).unwrap();
    assert!(!proof.verify(&fake_entry, &two_leaf_root));
}
